import{_ as t,c as e,o as a,a4 as s}from"./chunks/framework.dBUWB6Kx.js";const p=JSON.parse('{"title":"箭头函数 this 指向问题","description":"","frontmatter":{},"headers":[],"relativePath":"modules/web/ES6/箭头函数 this 指向问题.md","filePath":"modules/web/ES6/箭头函数 this 指向问题.md","lastUpdated":1773858860000}'),i={name:"modules/web/ES6/箭头函数 this 指向问题.md"},l=s('<h1 id="箭头函数-this-指向问题" tabindex="-1">箭头函数 this 指向问题 <a class="header-anchor" href="#箭头函数-this-指向问题" aria-label="Permalink to &quot;箭头函数 this 指向问题&quot;">​</a></h1><ul><li>ES6 中定义的时候绑定 this 的具体含义，应该继承的是父执行上下文里面的 this</li><li>简单对象（非函数）是没有执行上下文的</li><li>箭头函数中，this 指向的固定化，并不是因为箭头函数内部有绑定 this 的机制，实际原因是箭头函数根本没有自己的 this，导致内部的 this 就是外层代码块的 this。正是因为它没有 this，所以也就不能用作构造函数。</li></ul><h3 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h3><ul><li><a href="https://www.cnblogs.com/lingnweb/p/9882082.html" target="_blank" rel="noreferrer">es6 箭头函数 this 指向问题</a></li></ul>',4),_=[l];function h(o,r,n,c,d,m){return a(),e("div",null,_)}const f=t(i,[["render",h]]);export{p as __pageData,f as default};
